#include <fstream>
#include <iostream>
#include <optional>
#include <sstream>
#include <string>

std::optional<int> parse_quantity(const std::string& line) {
    std::istringstream in(line);
    int qty{};
    char extra{};
    if (!(in >> qty) || (in >> extra)) return std::nullopt;   // not a number, or junk after.
    if (qty < 1 || qty > 99) return std::nullopt;             // range.
    return qty;
}

int main() {
    std::ifstream file("orders.txt");
    if (!file) { std::cerr << "cannot open orders.txt\n"; return 1; }
    std::ofstream out("valid.txt");
    std::string line;
    int line_no = 0;
    while (std::getline(file, line)) {                // loop on the read itself.
        ++line_no;
        if (auto q = parse_quantity(line)) out << *q << '\n';
        else std::cerr << "line " << line_no << ": invalid\n";
    }
    if (file.bad()) { std::cerr << "read error\n"; return 1; }
    if (!out) { std::cerr << "write error\n"; return 1; }
}
